{
  "executive_summary": "E2E Driver repeatedly used concrete models and real-life examples (cake, shapes) so students could identify fractions; strongest area is Lesson Plan Fidelity (clear objectives and aligned tasks). Key growth area is Effective Feedback (C3): the teacher gives praise and correct answers but rarely gives specific, actionable feedback telling students what to do next. The teacher reflected that pacing supported learning and plans to give quieter students more wait time — this intention strengthens recommendations about deliberate wait-time and targeted follow-up.",
  "talk_time": {},
  "questions": {},
  "goal1_formative_assessment": {
    "domain": "high_leverage_practices",
    "original": {
      "domain_max": 8,
      "domain_score": 4,
      "indicators": [
        {
          "id": "C1",
          "name": "Quality Questioning (Bloom's Aligned)",
          "score": 1,
          "evidence": "Most questions are short recall or counting prompts; a few open prompts occur but fewer than three and there is little follow-up on a student's reasoning. Example open prompt: \"[01:34] Teacher: 'اس کی ڈیفینیشن کوئی بتا سکتا ہے؟ ہوتا کیا ہے?'\"",
          "evidence_summary": "Teacher asks mainly recall/counting questions; one open question appears but minimal follow-up."
        },
        {
          "id": "C2",
          "name": "Responsive Re-explanation & Adaptive Teaching",
          "score": 2,
          "evidence": "Teacher uses different representations (circle model, cake analogy, coloured sets) to make fraction concrete.",
          "evidence_summary": "Multiple representations used to re-explain the concept."
        },
        {
          "id": "C3",
          "name": "Effective Feedback",
          "score": 0,
          "evidence": "Feedback is mostly praise or restating answers rather than diagnostic or directive next-step feedback (e.g. 'ٹھیک ہے', 'شاباش').",
          "evidence_summary": "Feedback is general; lacks specific actionable next steps."
        },
        {
          "id": "C4",
          "name": "Student Agency & Voice",
          "score": 1,
          "evidence": "Students volunteer answers and personal connections but are not routinely asked to choose methods or justify decisions.",
          "evidence_summary": "Student voice exists but agency in method or strategy choice is limited."
        }
      ]
    }
  },
  "goal2_student_engagement": {
    "domain": "student_engagement",
    "original": {
      "domain_max": 10,
      "domain_score": 7,
      "indicators": [
        {
          "id": "D1",
          "name": "Diversity of Conceptual Expression",
          "score": 1,
          "evidence": "Students mostly repeat teacher wording or give short answers (counts and label repetition). Example repeated phrasing: \"[06:31] Teacher: 'جو اوپر جو نمبر ہوتا ہے، اس کو کیا کہتے ہیں؟ نمبریٹر.' Student: '[06:32] Student: نمبریٹر.'\"",
          "evidence_summary": "Student responses mainly echo teacher phrases, showing limited independent phrasings."
        },
        {
          "id": "D2",
          "name": "Student Reasoning in Responses",
          "score": 1,
          "evidence": "Teacher asks for reasons once but student responses are brief and not substantive (e.g. '[12:25] Teacher: \"کیوں?\"' followed by a repetitive response).",
          "evidence_summary": "Reasoning prompts exist but answers are short and not explanatory."
        },
        {
          "id": "D3",
          "name": "Student-Initiated Questions",
          "score": 1,
          "evidence": "Students ask procedural questions (e.g. about the test) but not deep conceptual questions.",
          "evidence_summary": "Student questions are mostly procedural rather than conceptual."
        },
        {
          "id": "D4",
          "name": "Spontaneous Transfer & Connection-Making",
          "score": 2,
          "evidence": "A student linked cake example to a birthday when prompted: '[03:28] Student: \"My little brother's birthday.\"'",
          "evidence_summary": "Prompted real-world connection was made by a student."
        },
        {
          "id": "D5",
          "name": "Visible Learning Progression Across the Lesson",
          "score": 2,
          "evidence": "Students moved from simple identification to using fraction vocabulary and fuller phrasing across the lesson.",
          "evidence_summary": "Progression visible: identification → vocabulary use."
        }
      ]
    }
  },
  "goal3_quality_content": {
    "domain": "teacher_subject_knowledge_and_lesson_plan",
    "original": {
      "teacher_subject_knowledge": {
