        "indicators": [
          {
            "id": "F1",
            "name": "Content Accuracy",
            "score": 2,
            "evidence": "Teacher accurately defines numerator/denominator and proper fractions with examples ('[06:31] نمبریٹر', '[06:38] ڈینومینیٹر')."
          },
          {
            "id": "F2",
            "name": "Use of Academic Language",
            "score": 2,
            "evidence": "Key terms used and repeated: 'نمبریٹر', 'ڈینومینیٹر', 'پروپر فیکشن'."
          },
          {
            "id": "F3",
            "name": "Anticipation of Student Misconceptions",
            "score": 1,
            "evidence": "Teacher corrects errors by example (e.g. 3/3 not a proper fraction) but does not explicitly name common misconceptions."
          },
          {
