            "score": 0,
            "evidence": "Tasks are routine identification and labelling; no non-routine problems or extended think time."
          }
        ]
      },
      "lesson_plan_fidelity": {
        "domain_max": 14,
        "domain_score": 11,
        "indicators": [
          {
            "id": "B1",
            "name": "Instructional Clarity & Learning Objectives",
            "score": 2,
            "evidence": "Teacher states the lesson focus and gives a concrete student task: '[08:11] \"آج ہم پڑھ رہے ہیں پروپر فیکشن\"' and '[14:34] \"پروپر فیکشن لکھنا ہے\"'."
          },
          {
            "id": "B2",
            "name": "Lesson Structure & Sequence",
            "score": 2,
            "evidence": "Teacher signals phase changes aloud: '[05:17] \"اب ہم ایک اور شیپ بناتے ہیں\"'."
          },
          {
            "id": "B3",
            "name": "Activities & Tasks Alignment",
            "score": 2,
            "evidence": "Activities (models, cake analogy, drawing, test) align with objective of proper fractions."
          },
          {
            "id": "B4",
            "name": "Activation of Prior Knowledge",
            "score": 1,
            "evidence": "Brief reference to prior reading: '[01:13] \"آپ نے فیکشن کے بارے میں پڑھا ہے\"'."
          },
          {
            "id": "B5",
            "name": "Meaningful & Real-World Connections",
            "score": 2,
            "evidence": "Cake-sharing example developed and linked to equal parts; student connected to birthday."
          },
          {
            "id": "B6",
            "name": "Differentiation / Catering to Learning Levels",
            "score": 0,
            "evidence": "One whole-class task; no distinct scaffolds or extension tasks observed."
          },
          {
            "id": "B7",
            "name": "Lesson Closure & Consolidation",
            "score": 2,
            "evidence": "Teacher elicits student summary and sets a short written test: '[08:31] student summary; [12:59] test prompt.'"
          }
        ]
      }
