  "goal4_classroom_interaction": {
    "domain": "peer_and_group_interactions_summary",
    "original": {
      "domain_max": 5,
      "domain_score": 3,
      "evidence": "Interactions are mostly whole-class teacher-led Q&A with choral responses and some individual contributions. Structures for peer collaboration or norms were not observed; interactions were meaningful when teacher prompted."
    }
  },
  "goal5_classroom_management": {
    "domain": "classroom_management_and_culture",
    "original": {
      "classroom_management": {
        "observations": "Teacher used clear spoken transitions and general behaviour directives (e.g., 'بیٹا، بیٹھ جاؤ') but explicit routines and differentiated management structures were limited."
      },
      "visibility_of_materials": "Learning aids and models were visible and used; classroom photo shows supportive visual arrays though routine charts were not visible.",
      "classroom_culture": "Teacher treated students respectfully and created an inclusive environment with few lapses noted."
    }
  },
  "strengths": [
    {
      "title": "Concrete representations and real-life links",
      "evidence": "Teacher used a circle model, cake-sharing and coloured sets to make fractions concrete: \"[00:22] 'یہ ایک ماڈل ہے...'\" and \"[03:00] 'مثلاً... یہ کیک ہے.'\"",
      "analysis": "These concrete representations supported students moving from simple identification to using fraction vocabulary (numerator/denominator). The teacher also reflected that pacing supported learning, suggesting she intentionally used time to move across representations.",
      "impact": "Because the teacher paced the lesson through multiple concrete representations, students progressed from single-word identifications to repeating and using academic terms. The teacher's plan to give quieter students more wait time can strengthen this impact by allowing more students to form conceptual links aloud."
    }
  ],
  "growth_opportunities": [
    {
      "area": "Effective Feedback (C3)",
      "observation": "Feedback observed is largely praise and restatement; there are few instances of diagnostic guidance telling a student what to change next.",
      "rationale": "The teacher acknowledged pacing helped but did not mention specific follow-up moves after student answers — targeted, actionable feedback would help students revise and deepen understanding.",
      "strategies": [
        "After a student answer, name one specific strength and give one clear next step (e.g., 'Good count — now write the numerator on top and try saying the fraction aloud').",
        "Model a corrective re-do: pick one student response, state precisely what to change, and ask the student to try again.",
        "Use quick written checks (one-line corrections) so students can apply feedback immediately."
      ]
    },
    {
      "area": "Wait-time & Inclusive Participation",
      "observation": "Many students gave brief or choral replies; several capable students remained quiet or produced short answers.",
      "rationale": "Teacher identified pacing as a strength and said she would give quieter students more time. Turning that intention into specific wait-time strategies will increase reasoning and fuller student responses.",
      "strategies": [
        "Intentionally use a 3–5 second wait after asking a question; count silently or visually to yourself before accepting answers.",
        "Pair think time with a quick turn-and-talk: quiet students can first discuss with a neighbour before answering to the whole class.",
        "Use targeted cold-call routines (e.g., 'I will ask three students today to explain their thinking') so quieter students are prepared to speak."
      ]
    },
    {
      "area": "Differentiation (B6)",
      "observation": "All students received the same task; no easier scaffolds or extension tasks were given.",
      "rationale": "Teacher's awareness of pacing is helpful; pairing that with differentiated tasks will allow quiet or struggling students to show understanding at the right level.",
      "strategies": [
        "Prepare two worksheet versions: one with simpler halves/quarters and one with extension comparing fractions.",
        "Use mixed-ability pairs where stronger students explain while others use manipulatives; teacher circulates with targeted prompts."
      ]
    },
    {
      "area": "Problem Solving / Productive Struggle (F5)",
      "observation": "Tasks were routine identification and labelling without sustained think time or multi-step reasoning.",
      "rationale": "Allowing deliberate think time aligns with the teacher's plan to vary pacing; adding one non-routine task will promote deeper reasoning.",
      "strategies": [
        "Introduce a short non-routine task (e.g., 'How many ways can you make 1/2 using different shapes?') and allow 2–3 minutes silent think time.",
        "Ask students to justify their choices in one sentence, then share with a partner before class discussion."
      ]
    }
  ],
  "scores": {
    "max_marks": 103,
    "overall_marks": 17,
    "has_lesson_plan": false,
    "overall_max_marks": 28,
    "overall_percentage": 60.7,
    "indicators_applicable": 21,
    "indicators_not_applicable": 5,
    "domains": {
      "student_engagement_domain_score": 7,
      "lesson_plan_fidelity_domain_score": 11,
      "high_leverage_practices_domain_score": 4,
      "teacher_subject_knowledge_domain_score": 6
    }
  },
  "recommendations": [
    "Use targeted, specific feedback: after each student response name one correct aspect and give one concrete next step (e.g., 'Good count — now write the numerator on top and try again'). The teacher already plans to manage pacing; pair that with explicit feedback moves.",
    "Build quick differentiation: prepare a simple scaffold (manipulatives) for learners needing support and one extension task for faster students. Use the teacher's intended extra wait-time to circulate and provide targeted supports.",
    "Introduce one short non-routine problem and allow 1–2 minutes think time so students practice productive struggle and justify their reasoning.",
    "Structure wait-time and participation routines: intentionally pause 3–5 seconds after a question, use think-pair-share, and plan to cold-call a few students so quieter learners have time and expectation to respond."
  ],
  "notable_moments": [
    {
      "scope": "individual",
      "named_student": null,
      "what_happened": "The teacher showed a model (likely a circle) and asked what it was. A student said 'circle.' The teacher confirmed but then asked how many parts it could be divided into. A student answered '4.'",
      "approx_time_phrase": "at the start",
      "significance_reason_en": "The student correctly identifies the shape but the teacher's pivot to partitioning reveals the lesson's goal. The student's quick, correct answer of '4' shows they are ready to engage with partitioning, but it's a simple count, not yet connected to fraction notation."
    },
    {
      "scope": "individual",
      "named_student": null,
      "what_happened": "The teacher asked for the definition of a fraction. A student gave a procedural answer: 'the way one is closed and below 4 comes, above 3.' The teacher acknowledged but pressed for a definition.",
      "approx_time_phrase": "around minute one",
      "significance_reason_en": "The student's answer ('above 3, below 4') reveals they are recalling fraction notation but are expressing it in a confused, procedural way. This shows a gap in articulating the core concept of 'parts of a whole.'"
    },
    {
      "scope": "individual",
      "named_student": null,
      "what_happened": "A student tried to explain a fraction example involving the numbers 9 and 10, saying '9 and 10 below, and 9 above.' The teacher tried to clarify, asking '9 we have to write above, and 10?'",
      "approx_time_phrase": "around minute two",
      "significance_reason_en": "The student's explanation is muddled, mixing up the placement of numerator and denominator. The teacher's follow-up is an attempt to correct this, highlighting a common point of confusion in writing fractions."
    },
    {
      "scope": "individual",
      "named_student": null,
      "what_happened": "The teacher used a real-world example of cutting a cake. A student said, 'We do part.' The teacher affirmed, saying they make 'equal parts so that there is no fight.'",
      "approx_time_phrase": "around minute three",
      "significance_reason_en": "This is a good conceptual anchor (cake/equal parts), but the teacher's explanation focuses on social fairness ('no fight') rather than explicitly linking it back to the mathematical definition of a fraction as equal parts of a whole."
    },
    {
      "scope": "individual",
      "named_student": null,
      "what_happened": "The teacher showed a model with 8 parts and asked how many were colored. A student started counting all parts ('1,2,3...8') and then said, 'Above to write, and 8 below.'",
      "approx_time_phrase": "around minute five",
      "significance_reason_en": "The student automatically counts total parts (8) for the denominator but struggles to identify the numerator (how many are colored). They state the structure ('above, below') but cannot fill in the specific numbers, showing a gap in applying the concept to a new visual."
    },
    {
      "scope": "individual",
      "named_student": null,
      "what_happened": "The teacher asked if '3, 7' or '7, 3' is a proper fraction. A student said '3, 7.' The teacher asked why, and the student repeated '3, 7, 3, 7, 3.' The teacher then gave a counterexample with equal numbers.",
      "approx_time_phrase": "near the end of the lesson",
      "significance_reason_en": "The student correctly identifies '3/7' as proper but cannot articulate the rule (numerator < denominator). Their repetitive answer shows reliance on pattern recognition rather than conceptual rule understanding."
    }
  ],
  "domain4_professional_responsibilities": {
    "reflection_quality": "Teacher offers brief, focused reflection noting pacing supported learning and a specific next step (allowing quieter students more time). This shows practical reflection on instructional timing.",
    "self_awareness": "Teacher recognizes a concrete aspect of practice (pacing and student response time) and acknowledges a change to make (give quieter students more time).",
    "growth_orientation": "Teacher demonstrates a growth mindset by identifying a tweak to practice (increase wait-time) and expressing willingness to try it next lesson.",
    "professional_learning_needs": "Teacher would benefit from strategies to increase meaningful participation (structured wait-time, think-pair-share, cold-call norms) and from methods to convert choral responses into individually reasoned answers.",
    "score": 3,
    "justification": "Teacher demonstrates solid self-awareness and a growth orientation with a specific, actionable change (wait-time for quieter students). The reflection is constructive but brief — a higher score would require deeper analysis linking the change to specific incidents or evidence of trial strategies."
  },
